sourceCode.css:
html{scroll-behavior: smooth;}
body{min-height: 100vh;}
[class*="scroll-fade"], [class*="fade-up"], [class*="reveal"], [data-aos]{opacity: 1 !important; visibility: visible !important; transform: none !important;}
:root{--site-bg: #f4f5f3; --site-surface: #ffffff; --site-ink: #151817; --site-muted: #5e6762; --site-line: #d7ddd8; --site-accent: #d9652b; --site-accent-strong: #ad451d; --site-accent-text: #ffffff; --site-accent-soft: #fff0e8; --site-diagram: #e8ece8; --site-tint: #eef4f0; --site-radius: 0.25rem; --site-font: "Geist", -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Noto Sans SC", "Microsoft YaHei", sans-serif; --site-heading-font: "Geist", -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Noto Sans SC", "Microsoft YaHei", sans-serif; --site-data-font: "Geist Mono", "SFMono-Regular", "Cascadia Code", "PingFang SC", "Noto Sans SC", "Microsoft YaHei", monospace; --site-container: 1200px; --site-gutter: 48px; --site-gutter-narrow: 32px; --site-section-space: 80px; --site-section-space-narrow: 52px; --site-h1: clamp(34px, 4.6vw, 58px); --site-h1-narrow: clamp(30px, 8vw, 34px); --site-h1-fit-min: 24px; --site-brand-fit-min: 11px; --site-brand-size: clamp(11px, 3.2vw, 17px); --site-h1-display: clamp(30px, 4.8vw, 64px); --site-h2: clamp(27px, 3vw, 38px); --site-h1-leading: 1.1; --site-h1-tracking: -0.03em; --site-heading-wrap: normal; --site-heading-break: keep-all; --site-heading-max: 16em; --site-heading-text-wrap: balance; --site-heading-tracking: -0.02em; --site-card-radius: 0; --site-media-radius: 0; --site-panel-radius: 0; --site-tile-radius: 0; --site-control-radius: 0; --site-primary-bg: var(--site-accent-strong); --site-primary-hover: var(--site-ink); --site-plate-bg: var(--site-ink); --site-plate-ink: var(--site-accent-text); --site-plate-copy: var(--site-accent-text); --site-plate-muted: rgba(255, 255, 255, 0.66); --site-plate-border: none; --site-specs-top: 3px solid var(--site-accent); --site-spec-gap: 0; --site-spec-cell-bg: transparent; --site-key-bg: transparent; --site-key-gap: 0; --site-key-divider: var(--site-rule); --site-footer-bg: var(--site-ink); --site-footer-ink: rgba(255, 255, 255, 0.72); --site-footer-head: #fff; --site-footer-top: none; --site-eyebrow: var(--site-muted); --site-hero-bg: var(--site-surface); --site-frame-pad: 0; --site-frame-bg: transparent; --site-frame-border: none; --site-eyebrow-bg: transparent; --site-eyebrow-pad: 0; --site-head-rule: none; --site-head-pad: 0; --site-value-ink: var(--site-ink); --site-keys-border: var(--site-rule); --site-card-edge: none; --site-badge-edge: none; --site-panel-edge: none; --site-step-top: none; --site-list-marker: 0; --site-catalog-row: minmax(0, 11em) minmax(0, 1fr); --site-spec-table-border: var(--site-rule); --site-spec-table-head: transparent; --site-panel-bg: var(--site-tint); --site-panel-copy-bg: transparent; --site-form-card: var(--site-surface); --site-group-columns: minmax(0, 12em) minmax(0, 1fr); --site-rule: 1px solid var(--site-line); --site-rule-strong: 2px solid var(--site-ink);}
*{box-sizing: border-box;}
html{background: var(--site-bg); color: var(--site-ink); font-family: var(--site-font); overflow-x: hidden; -webkit-font-smoothing: antialiased; scroll-behavior: smooth;}
:where(h1, h2, h3, h4, h5, h6){font-family: var(--site-heading-font, var(--site-font));}
@media (prefers-reduced-motion: reduce){html{scroll-behavior: auto;}}
body{margin: 0px; min-width: 320px; background: var(--site-bg); color: var(--site-ink); overflow-x: hidden;}
a{color: inherit; text-decoration: none;}
button, input, textarea{font: inherit;}
img{display: block; max-width: 100%;}
[hidden]{display: none !important;}
.sitecraft-container{width: min(100% - var(--site-gutter), var(--site-container)); margin: 0px auto;}
.sitecraft-btn{display: inline-flex; align-items: center; justify-content: center; min-height: 46px; padding: 0px 22px; border: 1px solid transparent; border-radius: var(--site-control-radius); font-size: 15px; font-weight: 650; cursor: pointer;}
.sitecraft-primary{background: var(--site-primary-bg); color: var(--site-plate-ink);}
.sitecraft-primary:hover{background: var(--site-primary-hover);}
.sitecraft-secondary{background: var(--site-surface); border-color: var(--site-line); color: var(--site-ink);}
.sitecraft-secondary:hover{border-color: var(--site-ink);}
a:focus-visible, button:focus-visible, summary:focus-visible{outline: 2px solid var(--site-accent); outline-offset: 2px;}
.sitecraft-section{padding: var(--site-section-space) 0; border-bottom: var(--site-rule);}
.sitecraft-section-head{display: flex; justify-content: space-between; align-items: end; gap: 32px; margin-bottom: 36px; padding-bottom: var(--site-head-pad); border-bottom: var(--site-head-rule);}
.sitecraft-section h2{margin: 0px; font-size: var(--site-h2); letter-spacing: var(--site-heading-tracking); line-height: 1.15;}
.sitecraft-section-intro{margin: 0px; max-width: 32em; color: var(--site-muted); font-size: 16px; line-height: 1.6;}
.sitecraft-pair{padding: var(--site-section-space) 0; border-bottom: var(--site-rule);}
.sitecraft-pair:not(:has(> .sitecraft-container > section:not([data-sitecraft-section-hidden="true"]))){display: none;}
.sitecraft-pair > .sitecraft-container{display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 420px), 1fr)); gap: 56px;}
.sitecraft-list h2{margin: 0px 0px 8px; font-size: 26px; letter-spacing: -0.02em;}
.sitecraft-list .sitecraft-section-intro{margin-bottom: 20px; font-size: 15px;}
.sitecraft-catalog-grid{border-top: var(--site-rule-strong);}
.sitecraft-catalog-card{display: grid; grid-template-columns: minmax(0px, 11em) minmax(0px, 1fr); gap: 16px; padding: 15px 0px; border-radius: var(--site-card-radius); border-bottom: var(--site-rule);}
.sitecraft-catalog-card h3{margin: 0px; font-size: 16px; font-weight: 650;}
.sitecraft-catalog-card p{margin: 0px; color: var(--site-muted); line-height: 1.55;}
.sitecraft-nameplate-cell dd, .sitecraft-hero-spec dd, .sitecraft-product-key dd, .sitecraft-product-specs td{word-break: keep-all; overflow-wrap: anywhere;}
.sitecraft-compare-value, .sitecraft-compare-extra dd{word-break: keep-all; overflow-wrap: anywhere;}
.sitecraft-nameplate-cell dd, .sitecraft-hero-spec dd, .sitecraft-index-spec-value, .sitecraft-equipment-quantity{font-family: var(--site-data-font, var(--site-font));}
.sitecraft-product-key dd, .sitecraft-product-specs td{font-family: var(--site-data-font, var(--site-font));}
.sitecraft-compare-value, .sitecraft-compare-extra dd, .sitecraft-band-line dd{font-family: var(--site-data-font, var(--site-font));}
.sitecraft-rule{height: 4px; background: var(--site-accent);}
.sitecraft-nav{position: relative; z-index: 5; background: var(--site-surface); border-bottom: var(--site-rule);}
.sitecraft-nav-inner{display: flex; align-items: center; justify-content: space-between; gap: 28px; min-height: 72px;}
.sitecraft-brand{--sitecraft-brand-mark-width: 30px; --sitecraft-brand-gap: 12px; display: flex; align-items: center; gap: var(--sitecraft-brand-gap); min-width: 0px; font-weight: 700; font-size: 18px; letter-spacing: -0.01em;}
.sitecraft-brand-mark{width: var(--sitecraft-brand-mark-width); height: 30px; flex: 0 0 auto; background: var(--site-ink); position: relative;}
.sitecraft-brand-mark::after{content: ""; position: absolute; inset: 0px; background: var(--site-accent); clip-path: polygon(100% 0px, 100% 100%, 0px 100%);}
.sitecraft-brand-name{min-width: 0px; line-height: 1.15; white-space: normal; word-break: keep-all; overflow-wrap: normal; text-wrap-style: balance;}
.sitecraft-nav-links{display: flex; align-items: center; gap: 26px; font-size: 14px; color: var(--site-muted);}
.sitecraft-nav-links a:hover{color: var(--site-ink);}
.sitecraft-nav-tools{display: flex; align-items: center; gap: 12px; flex: 0 0 auto;}
.sitecraft-locale-switch{display: inline-flex; border: 1px solid var(--site-line);}
.sitecraft-locale-switch button{border: 0px; background: transparent; padding: 7px 10px; font-size: 12px; font-weight: 700; color: var(--site-muted); cursor: pointer;}
.sitecraft-locale-switch button.active{background: var(--site-ink); color: rgb(255, 255, 255);}
.sitecraft-nav .sitecraft-btn{min-height: 40px; padding: 0px 16px; font-size: 14px;}
.sitecraft-menu{display: none; position: relative;}
.sitecraft-menu summary{list-style: none; cursor: pointer; padding: 9px 14px; border: 1px solid var(--site-line); font-size: 14px; font-weight: 600;}
.sitecraft-menu summary::-webkit-details-marker{display: none;}
.sitecraft-menu-panel{position: absolute; right: 0px; top: calc(100% + 8px); min-width: 210px; display: grid; background: var(--site-surface); border: 1px solid var(--site-line); box-shadow: rgba(0, 0, 0, 0.08) 0px 14px 30px;}
.sitecraft-menu-panel a{padding: 13px 16px; border-bottom: var(--site-rule); font-size: 15px;}
.sitecraft-menu-panel a:last-child{border-bottom: 0px;}
.sitecraft-nav-short .sitecraft-brand-mark{background: transparent; border: 1px solid var(--site-accent); border-radius: var(--site-control-radius);}
.sitecraft-nav-short .sitecraft-brand-mark::after{background: var(--site-accent); opacity: 0.22;}
.sitecraft-nav-short .sitecraft-nav-links{gap: 22px;}
.sitecraft-hero{background: var(--site-hero-bg); border-bottom: var(--site-rule);}
.sitecraft-hero-grid{display: grid; grid-template-columns: var(--site-hero-columns, minmax(0, 1fr) minmax(0, 1.05fr)); gap: 56px; align-items: center; padding: 64px 0px 72px;}
.sitecraft-hero-grid > [data-sc-part="copy"]{min-width: 0px;}
.sitecraft-hero-grid > [data-sc-part="copy"]:has(h1[style*="--sitecraft-title-run"]){container-type: inline-size;}
.sitecraft-hero[data-sitecraft-hero-mode="none"] .sitecraft-hero-grid{grid-template-columns: minmax(0px, 1fr);}
.sitecraft-eyebrow{margin: 0px 0px 18px; padding: var(--site-eyebrow-pad); background: var(--site-eyebrow-bg); font-size: 13px; color: var(--site-eyebrow); letter-spacing: 0.02em;}
.sitecraft-hero h1{margin: 0px; max-width: var(--site-heading-max); font-size: var(--site-h1); line-height: var(--site-h1-leading); letter-spacing: var(--site-h1-tracking); font-weight: 750; text-wrap: var(--site-heading-text-wrap); word-break: var(--site-heading-break); overflow-wrap: var(--site-heading-wrap);}
.sitecraft-hero h1[style*="--sitecraft-title-run"]{font-size: max(var(--site-h1-fit-min, 24px), min(var(--site-h1-fit-size, var(--site-h1)), calc(100cqw / var(--sitecraft-title-run)))); word-break: var(--site-fit-heading-break, keep-all); overflow-wrap: normal; text-wrap: balance;}
.sitecraft-hero-copy{margin: 22px 0px 0px; max-width: 34em; font-size: 18px; line-height: 1.6; color: var(--site-muted);}
.sitecraft-hero-actions{display: flex; flex-wrap: wrap; gap: 12px; margin-top: 32px;}
.sitecraft-hero-visual{margin: 0px;}
.sitecraft-hero-photo{width: 100%; aspect-ratio: 4 / 3; object-fit: cover; background: var(--site-diagram);}
.sitecraft-hero-credit{margin: 8px 0px 0px; font-size: 12px; color: var(--site-muted);}
.sitecraft-image-gallery{display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px; margin-top: 18px;}
.sitecraft-image-gallery[hidden]{display: none;}
.sitecraft-image-gallery figure{margin: 0px; min-width: 0px;}
.sitecraft-image-gallery img{display: block; width: 100%; aspect-ratio: 4 / 3; object-fit: cover; border-radius: var(--site-media-radius); background: var(--site-diagram);}
.sitecraft-image-gallery figcaption{margin-top: 5px; color: var(--site-muted); font-size: 12px; line-height: 1.4;}
.sitecraft-nameplate{margin: 0px; padding: 32px 34px; display: grid; grid-template-columns: 1fr 1fr; gap: 24px 28px; border-radius: var(--site-media-radius); background: var(--site-plate-bg); color: var(--site-plate-copy);}
.sitecraft-nameplate-cell dt{font-size: 13px; color: var(--site-plate-muted);}
.sitecraft-nameplate-cell dd{margin: 6px 0px 0px; font-size: 26px; font-weight: 700; letter-spacing: -0.02em; font-variant-numeric: tabular-nums;}
.sitecraft-hero-specs{background: var(--site-plate-bg); color: var(--site-plate-copy); border-top: var(--site-specs-top);}
.sitecraft-hero-specs dl{margin: 0px auto; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0px, 1fr);}
.sitecraft-hero-spec{padding: 18px 22px; background: var(--site-spec-cell-bg); border-left: 1px solid rgba(255, 255, 255, 0.14);}
.sitecraft-hero-spec:last-child{border-right: 1px solid rgba(255, 255, 255, 0.14);}
.sitecraft-hero-spec dt{font-size: 12px; color: var(--site-plate-muted);}
.sitecraft-hero-spec dd{margin: 5px 0px 0px; font-size: 20px; font-weight: 700; font-variant-numeric: tabular-nums;}
.sitecraft-statement{padding: 72px 0px 60px;}
.sitecraft-statement:has(h1[style*="--sitecraft-title-run"]){container-type: inline-size;}
.sitecraft-statement h1{max-width: 18em; font-size: var(--site-h1-display); line-height: 1.06; letter-spacing: -0.03em;}
.sitecraft-statement-foot{display: grid; grid-template-columns: minmax(0px, 1fr) auto; gap: 24px 56px; align-items: end; margin-top: 28px;}
.sitecraft-statement .sitecraft-hero-copy{margin: 0px; max-width: 40em; text-wrap: pretty;}
.sitecraft-statement .sitecraft-hero-actions{margin-top: 0px; justify-content: flex-end;}
.sitecraft-statement-foot:has(> .sitecraft-hero-copy[hidden]) .sitecraft-hero-actions{justify-content: flex-start;}
.sitecraft-statement-specs{margin-top: 32px; background: var(--site-surface); border-top: 2px solid var(--site-accent);}
.sitecraft-statement-specs dl{margin: 0px; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0px, 1fr);}
.sitecraft-statement-specs .sitecraft-hero-spec{padding: 20px 22px 22px; border: 0px;}
.sitecraft-statement-specs .sitecraft-hero-spec:not(:first-child){border-left: var(--site-rule);}
.sitecraft-statement-specs .sitecraft-hero-spec dt{font-size: 12px; line-height: 1.4; color: var(--site-muted); word-break: keep-all; overflow-wrap: anywhere;}
.sitecraft-statement-specs .sitecraft-hero-spec dd{margin: 8px 0px 0px; font-size: 24px; font-weight: 700; line-height: 1.2; letter-spacing: -0.015em; color: var(--site-ink); overflow-wrap: anywhere; text-wrap: balance;}
.sitecraft-cover-index{min-width: 0px; border-top: var(--site-index-top, var(--site-rule-strong));}
.sitecraft-cover-index > p{margin: 0px; padding: 14px 0px 12px; font-size: 13px; font-weight: 600; color: var(--site-muted); border-bottom: var(--site-index-row, var(--site-rule));}
.sitecraft-cover-index ul{margin: 0px; padding: 0px; list-style: none;}
.sitecraft-cover-index li{border-bottom: var(--site-index-row, var(--site-rule));}
.sitecraft-cover-index a{display: grid; grid-template-columns: minmax(0px, 1fr) auto auto; gap: 16px; align-items: baseline; padding: 16px 0px;}
.sitecraft-cover-index a::after{content: "→"; color: var(--site-accent-strong);}
.sitecraft-cover-index a:hover .sitecraft-cover-index-name{color: var(--site-accent-strong);}
.sitecraft-cover-index-name{font-size: 20px; font-weight: 700; line-height: 1.3; letter-spacing: -0.01em; overflow-wrap: anywhere;}
.sitecraft-cover-index-category{font-size: 13px; color: var(--site-muted); text-align: right; overflow-wrap: anywhere;}
.sitecraft-product-grid{display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 420px), 1fr)); gap: 24px;}
.sitecraft-product-card{container-type: inline-size; display: flex; flex-direction: column; background: var(--site-surface); border: var(--site-rule); border-radius: var(--site-card-radius);}
.sitecraft-product-media{aspect-ratio: 16 / 10; background: var(--site-diagram); overflow: hidden;}
.sitecraft-product-image{width: 100%; height: 100%; object-fit: cover;}
.sitecraft-product-body{flex: 1 1 0%; display: flex; flex-direction: column; gap: 14px; padding: 26px 28px 24px;}
.sitecraft-product-category{margin: 0px; font-size: 13px; font-weight: 600; color: var(--site-accent-strong);}
.sitecraft-product-card h3{margin: 0px; font-size: 24px; letter-spacing: -0.01em;}
.sitecraft-product-keys{margin: 0px; display: grid; grid-template-columns: repeat(3, minmax(0px, 1fr)); gap: var(--site-key-gap); background: var(--site-key-bg); border-top: var(--site-keys-border); border-bottom: var(--site-keys-border);}
.sitecraft-product-key{min-width: 0px; padding: 14px 12px 14px 0px;}
.sitecraft-product-key + .sitecraft-product-key{padding-left: 14px; border-left: var(--site-rule);}
.sitecraft-product-key dt{font-size: 12px; color: var(--site-muted);}
.sitecraft-product-key dd{min-width: 0px; margin: 4px 0px 0px; font-size: 18px; font-weight: 700; font-variant-numeric: tabular-nums; white-space: normal; word-break: normal; overflow-wrap: anywhere; text-wrap-style: balance;}
.sitecraft-product-card[data-sitecraft-product-photo="false"] .sitecraft-product-key dd{font-size: 22px;}
.sitecraft-product-summary, .sitecraft-index-summary{max-inline-size: 30em; text-wrap: pretty;}
.sitecraft-compare-summary{max-inline-size: 30em; text-wrap: pretty;}
.sitecraft-product-summary, .sitecraft-index-summary{word-break: keep-all; overflow-wrap: anywhere;}
.sitecraft-compare-summary{word-break: keep-all; overflow-wrap: anywhere;}
@container (min-width: 860px){.sitecraft-product-body{display: grid; grid-template-columns: minmax(0px, 1fr) minmax(0px, 30em); column-gap: 56px; align-content: start;}
.sitecraft-product-body > .sitecraft-product-summary{grid-area: 1 / 2 / span 5; align-self: start;}}
.sitecraft-product-summary{margin: 0px; color: var(--site-muted); line-height: 1.6;}
.sitecraft-product-more summary{cursor: pointer; list-style: none; font-size: 14px; font-weight: 600; color: var(--site-accent-strong);}
.sitecraft-product-more summary::-webkit-details-marker{display: none;}
.sitecraft-product-more summary::after{content: " +";}
.sitecraft-product-more[open] summary::after{content: " −";}
.sitecraft-product-specs{width: 100%; margin-top: 10px; border-collapse: collapse; font-size: 14px;}
.sitecraft-product-specs th, .sitecraft-product-specs td{padding: 9px 0px; border-bottom: var(--site-rule); text-align: left; vertical-align: top;}
.sitecraft-product-specs th{width: 44%; color: var(--site-muted); font-weight: 500;}
.sitecraft-product-specs td{font-variant-numeric: tabular-nums;}
.sitecraft-product-foot{margin-top: auto; padding-top: 6px; display: grid; gap: 6px;}
.sitecraft-product-ask{justify-self: start; font-size: 14px; font-weight: 650;}
.sitecraft-product-ask::after{content: " →";}
.sitecraft-product-ask:hover{color: var(--site-accent-strong);}
.sitecraft-product-image-credit{margin: 0px; font-size: 12px; color: var(--site-muted);}
.sitecraft-product-empty{margin: 0px; color: var(--site-muted);}
.sitecraft-image-gallery{display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 12px; margin-top: 24px;}
.sitecraft-image-gallery[hidden]{display: none;}
.sitecraft-image-gallery figure{margin: 0px; min-width: 0px;}
.sitecraft-image-gallery img{display: block; width: 100%; aspect-ratio: 4 / 3; object-fit: cover; border-radius: var(--site-card-radius); background: var(--site-diagram);}
.sitecraft-image-gallery figcaption{margin-top: 6px; color: var(--site-muted); font-size: 12px; line-height: 1.45;}
.sitecraft-product-card{box-shadow: 0 1px 0 var(--site-line);}
.sitecraft-product-rows{display: grid; gap: 20px;}
.sitecraft-product-rows .sitecraft-product-card{display: grid; grid-template-columns: minmax(0px, 300px) minmax(0px, 1fr); min-width: 0px;}
.sitecraft-product-rows .sitecraft-product-card[data-sitecraft-product-photo="false"]{grid-template-columns: 1fr; border-left: var(--site-card-edge);}
.sitecraft-product-rows .sitecraft-product-media{height: 100%; min-height: 220px; aspect-ratio: auto;}
.sitecraft-product-rows .sitecraft-product-body{min-width: 0px;}
.sitecraft-product-rows .sitecraft-product-keys{border: var(--site-keys-border);}
.sitecraft-product-groups{display: grid; gap: 44px;}
.sitecraft-product-group{display: grid; grid-template-columns: var(--site-group-columns, minmax(0, 12em) minmax(0, 1fr)); gap: 20px 44px; padding-top: 22px; border-top: var(--site-rule-strong);}
.sitecraft-product-group-title{margin: 0px; font-size: 21px; font-weight: 700; line-height: 1.3; letter-spacing: -0.01em; overflow-wrap: anywhere;}
.sitecraft-product-group-cards{display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 340px), 1fr)); gap: 20px;}
.sitecraft-product-groups .sitecraft-product-body{padding: 24px 26px 22px;}
.sitecraft-product-groups .sitecraft-product-card h4{margin: 0px; font-size: 21px; line-height: 1.3; letter-spacing: -0.01em; overflow-wrap: anywhere;}
.sitecraft-product-groups .sitecraft-product-keys{grid-template-columns: 1fr;}
.sitecraft-product-groups .sitecraft-product-key, .sitecraft-product-groups .sitecraft-product-key + .sitecraft-product-key{display: flex; justify-content: space-between; align-items: baseline; gap: 16px; padding: 10px 0px; border-left: 0px;}
.sitecraft-product-groups .sitecraft-product-key + .sitecraft-product-key{border-top: var(--site-rule);}
.sitecraft-product-groups .sitecraft-product-key dt{flex: 0 0 auto; max-width: 45%; font-size: 13px;}
.sitecraft-product-groups .sitecraft-product-key dd, .sitecraft-product-groups .sitecraft-product-card[data-sitecraft-product-photo="false"] .sitecraft-product-key dd{margin: 0px; min-width: 0px; font-size: 17px; text-align: right; white-space: normal; overflow-wrap: anywhere;}
.sitecraft-product-groups .sitecraft-product-specs td{overflow-wrap: anywhere;}
.sitecraft-look-industrial .sitecraft-product-group-title{padding-bottom: 10px; border-bottom: var(--site-rule-strong);}
.sitecraft-compare{display: grid; gap: 28px;}
.sitecraft-compare-series{display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr)); gap: 16px;}
.sitecraft-compare-series-card{display: flex; flex-direction: column; gap: 10px; min-width: 0px; padding: 22px 24px 20px; background: var(--site-surface); border-top: 3px solid var(--site-accent);}
.sitecraft-compare-series-card h3{margin: 0px; font-size: 21px; line-height: 1.3; letter-spacing: -0.01em; overflow-wrap: anywhere;}
.sitecraft-compare-summary{margin: 0px; color: var(--site-muted); line-height: 1.6;}
.sitecraft-compare-series-card .sitecraft-product-ask{align-self: flex-start; margin-top: auto; padding-top: 4px;}
