.sitecraft-terms-strip[data-sitecraft-entry-count] .sitecraft-commercial-term:nth-child(n){padding: 16px 0px 18px; border-left: 0px; border-top: var(--site-index-row, var(--site-rule));}
.sitecraft-terms-strip[data-sitecraft-entry-count] .sitecraft-commercial-term:first-child{border-top: 0px;}
.sitecraft-terms-strip .sitecraft-commercial-term p{font-size: 17px;}
.sitecraft-terms-strip .sitecraft-commercial-term:only-child p{font-size: 22px;}
.sitecraft-terms-side .sitecraft-commercial-term p{font-size: 16px;}
.sitecraft-terms-side .sitecraft-commercial-term:only-child p{font-size: 20px;}
.sitecraft-equipment-item{grid-template-columns: 1fr; gap: 5px; padding: 14px 0px;}
.sitecraft-equipment-item [data-sitecraft-equipment-spec]{grid-column: auto;}
.sitecraft-image-gallery{display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 12px; margin-top: 24px;}
.sitecraft-image-gallery[hidden]{display: none;}
.sitecraft-image-gallery figure{margin: 0px; min-width: 0px;}
.sitecraft-image-gallery img{display: block; width: 100%; aspect-ratio: 4 / 3; object-fit: cover; border-radius: var(--site-card-radius); background: var(--site-diagram);}
.sitecraft-image-gallery figcaption{margin-top: 6px; color: var(--site-muted); font-size: 12px; line-height: 1.45;}
.sitecraft-equipment-quantity{white-space: normal;}
.sitecraft-equipment-band .sitecraft-equipment-counted, .sitecraft-equipment-band .sitecraft-equipment-counted[data-sitecraft-entry-count]{grid-template-columns: repeat(2, minmax(0px, 1fr)); gap: 20px;}
.sitecraft-equipment-band .sitecraft-equipment-counted[data-sitecraft-entry-count="1"]{grid-template-columns: minmax(0px, 1fr);}
.sitecraft-equipment-band .sitecraft-equipment-counted .sitecraft-equipment-quantity{font-size: 34px;}
.sitecraft-equipment-band .sitecraft-equipment-plain{column-count: 1;}
.sitecraft-equipment-compact, .sitecraft-equipment-compact[data-sitecraft-entry-count]{grid-template-columns: minmax(0px, 1fr);}
.sitecraft-equipment-compact .sitecraft-equipment-item{grid-template-columns: minmax(0px, 1fr) auto; padding: 12px 0px;}
.sitecraft-quality-process-item{grid-template-columns: 1fr; gap: 5px; padding: 14px 0px;}
.sitecraft-quality-process-checklist .sitecraft-quality-process-item{padding: 16px;}
.sitecraft-quality-process-flow{display: block; position: relative; border-top: 0px; padding-left: 24px;}
.sitecraft-quality-process-flow::before{content: ""; position: absolute; inset: 0px auto 0px 7px; width: 1px; background: var(--site-line);}
.sitecraft-quality-process-flow .sitecraft-quality-process-item{padding: 16px 0px; border-bottom: 0px;}
.sitecraft-quality-process-flow .sitecraft-quality-process-item::after{top: 24px; right: auto; left: -21px; width: 12px;}
.sitecraft-history-item{grid-template-columns: 1fr; gap: 5px; padding: 14px 0px;}
.sitecraft-history-timeline{padding-left: 24px;}
.sitecraft-history-timeline .sitecraft-history-item{grid-template-columns: 1fr; gap: 5px; padding: 16px 0px;}
.sitecraft-history-alternating{display: block; padding-left: 24px;}
.sitecraft-history-alternating::before{inset: 0px auto 0px 7px;}
.sitecraft-history-alternating .sitecraft-history-item, .sitecraft-history-alternating .sitecraft-history-item:nth-child(2n), .sitecraft-history-alternating .sitecraft-history-item:nth-child(2n+1){width: 100%; margin: 0px; padding: 16px 0px; text-align: left;}
.sitecraft-history-alternating .sitecraft-history-item::before, .sitecraft-history-alternating .sitecraft-history-item:nth-child(2n)::before{left: -21px; right: auto; top: 21px;}
.sitecraft-process[data-sitecraft-entry-count="4"], .sitecraft-process[data-sitecraft-entry-count="5"], .sitecraft-process[data-sitecraft-entry-count="6"]{grid-template-columns: 1fr;}
.sitecraft-process[data-sitecraft-entry-count="5"] > .sitecraft-process-card[data-sitecraft-last-visible="true"]{grid-column: auto;}
.sitecraft-process-vertical .sitecraft-process-card{grid-template-columns: 36px minmax(0px, 1fr); gap: 0px 12px; padding: 18px 0px;}
.sitecraft-process-vertical .sitecraft-process-card::before{grid-row: 1; font-size: 22px;}
.sitecraft-process-vertical .sitecraft-process-card p{grid-area: 2 / 1 / auto / -1; margin-top: 8px;}
.sitecraft-cert-cards{grid-template-columns: 1fr;}
.sitecraft-inquiry-wrap{grid-template-columns: 1fr; gap: 36px;}
.sitecraft-inquiry-form{grid-template-columns: 1fr; padding: 20px;}
.sitecraft-band{gap: 24px;}
.sitecraft-band-line{padding: 16px 18px 18px;}
.sitecraft-band-line dd{font-size: 17px;}
.sitecraft-band-form{grid-template-columns: 1fr;}
.sitecraft-footer-inner{grid-template-columns: 1fr 1fr;}
.sitecraft-footer-about{grid-column: 1 / -1;}
.sitecraft-footer-line-inner{display: grid; grid-template-columns: minmax(0px, 1fr); align-items: start; gap: 16px;}
.sitecraft-footer-line .sitecraft-footer-contact{display: grid; gap: 8px;}
.sitecraft-footer-line [data-sitecraft-line]:has([data-sitecraft-contact="footer-phone"]){white-space: nowrap;}}
